-- Migration 572: a cancelled handover can be followed by a new one.
--
-- CrmHandover.BookingId was UNIQUE (one handover row per booking, cancelled
-- ones included), so once a handover appointment was cancelled the booking
-- could never be scheduled for handover again — the keys could not be given
-- through the system. Business decision 2026-10-14: a cancelled handover is
-- rebooked. Now: at most one handover per booking that is NOT Cancelled
-- (a filtered unique index); cancelled ones stay as history.
-- The old constraint's name was generated by SQL Server (differs per
-- database), so it is looked up. Safe to run again.
DECLARE @uq SYSNAME, @sql NVARCHAR(400);
SELECT TOP 1 @uq = kc.name
  FROM sys.key_constraints kc
  JOIN sys.index_columns ic ON ic.object_id = kc.parent_object_id AND ic.index_id = kc.unique_index_id
  JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id
 WHERE kc.parent_object_id = OBJECT_ID(N'dbo.CrmHandover') AND kc.type = 'UQ' AND c.name = N'BookingId'
   AND (SELECT COUNT(*) FROM sys.index_columns x WHERE x.object_id = kc.parent_object_id AND x.index_id = kc.unique_index_id) = 1;
IF @uq IS NOT NULL
BEGIN
  SET @sql = N'ALTER TABLE dbo.CrmHandover DROP CONSTRAINT ' + QUOTENAME(@uq);
  EXEC sp_executesql @sql;
END
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N'dbo.CrmHandover') AND name = N'UX_CrmHandover_Booking_Live')
  CREATE UNIQUE INDEX UX_CrmHandover_Booking_Live ON dbo.CrmHandover (BookingId) WHERE Status <> N'Cancelled';
GO
